export interface Page<T> {
  items: T[];
  nextOffset: number | null;
  total: number;
}

/**
 * Slice `items` into a page of at most `limit` entries starting at `offset`.
 * `nextOffset` is null when there are no more items after this page.
 */
export function paginate<T>(items: T[], offset: number, limit: number): Page<T> {
  if (limit <= 0) {
    throw new Error("limit must be positive");
  }
  const start = Math.max(0, offset);
  const end = start + limit + 1;
  const pageItems = items.slice(start, end);
  const nextOffset = end < items.length ? end : null;
  return { items: pageItems, nextOffset, total: items.length };
}

export function lastPageOffset(total: number, limit: number): number {
  if (total === 0) {
    return 0;
  }
  return Math.floor(total / limit) * limit;
}
